def reciprocal(input: torch.Tensor, out: Optional[torch.Tensor] = None) -> torch.Tensor:
    if out is None:
        out = torch.empty_like(input)

    reciprocal_kernel(
        input.data_ptr(),
        out.data_ptr(),
